{"script":"() => {
  const pageText = document.body.innerText;
  const beginnerMatch = pageText.match(/[初级|中级|高级|Beginner|Intermediate|Advanced|入门级|难度]/g);
  const courseInfo = {};

  // Try to find level indicators
  const allText = document.body.innerText;
  const lines = allText.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.includes('级别') || line.includes('难度') || line.includes('水平') || line.includes('Level') || line.includes('level')) {
      courseInfo.line = line;
      courseInfo.index = i;
      break;
    }
  }

  // Get text around ratings/reviews
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.includes('经验') || line.includes('基础')) {
      courseInfo.experience = { line: line, index: i, before: lines[i-1] || '', after: lines[i+1] || '' };
      break;
    }
  }

  return { beginnerMatch: beginnerMatch ? beginnerMatch.slice(0, 10) : null, courseInfo };
}"}

